'use strict';
function unitRank(u){return u.mythic?'#ff9ad8':u.type==='group'?['#d5b8ff','#b5e7ff','#ffdb82'][u.level-1]:rankColors[u.level-1]}
function portraitMarkup(u){const url=portraitURL(u);return '<span class="unit-art" aria-hidden="true">'+(url?'<img src="'+esc(url)+'" alt="" draggable="false" onerror="this.remove()">':'')+'<span>'+esc(nameOf(u).slice(0,3))+'</span></span>'}
function renderStage(){
 $('stageLevel').textContent='Lv.'+state.stageLevel;
 $('deployedCount').textContent=deployedCount()+' / '+capacity();$('tileCount').textContent=capacity()+'칸 개방 · '+(18-capacity())+'칸 잠김';
 $('capacityFill').style.width=(deployedCount()/capacity()*100)+'%';
 const cost=capacity()>=18?undefined:stageCosts[state.stageLevel-1],btn=$('expandStage');btn.textContent=cost?'확장 +2 · '+fmt(cost)+' G':'MAX LEVEL';btn.disabled=!cost||state.gold<cost||state.done||state.paused;
}
function renderBench(){
 const filter=$('filter').value,order=$('benchOrder').value,root=$('inventory');
 const all=state.units.filter(u=>u.slot<0);let us=all.filter(u=>filter==='all'||filter===u.type);
 const dps=u=>{const s=stats(u);return s.damage/s.interval};
 us.sort((a,b)=>order==='power'?dps(b)-dps(a)||a.id-b.id:order==='recent'?b.id-a.id:(b.type==='group')-(a.type==='group')||b.level-a.level||a.id-b.id);
 const stacks=new Map();for(const u of us){const key=JSON.stringify([u.type,u.type==='group'?u.gid:u.name,u.level,!!u.locked,!!u.mythic,u.mastery||0]);if(!stacks.has(key))stacks.set(key,[]);stacks.get(key).push(u)}
 $('count').textContent='대기 '+all.length+' · 보유 '+state.units.length;
 const signature=JSON.stringify([...stacks.values()].map(items=>[items.map(u=>u.id),items[0].level,items[0].mythic,items[0].mastery,items[0].type==='group'?progressFor(items[0].gid).level:0,items.map(u=>u.locked),items.some(u=>u.id===selected)]));
 if(root.dataset.signature===signature)return;root.dataset.signature=signature;
 root.innerHTML=stacks.size?[...stacks.values()].map(items=>{const u=items.find(u=>u.id===selected)||items[0];return '<button class="bench-token '+(u.id===selected?'selected':'')+'" data-unit="'+u.id+'" style="--rank:'+unitRank(u)+'" aria-label="'+esc(nameOf(u))+' '+items.length+'장">'+portraitMarkup(u)+(items.length>1?'<b class="stack-count">×'+items.length+'</b>':'')+'<strong>'+(u.locked?'🔒 ':'')+esc(nameOf(u))+'</strong><small>'+(u.type==='group'?(u.mythic?'MYTHIC +'+u.mastery:'★'.repeat(u.level))+' +'+progressFor(u.gid).level:'Lv.'+u.level)+'</small></button>'}).join(''):'<div class="empty-bench">—</div>';
}
function scrollBench(dir){$('inventory').scrollBy({left:dir*Math.max(180,$('inventory').clientWidth*.75),behavior:'smooth'})}

const autoCastKinds=['normal','group','gamble'];
let autoCastClock=0;
function setAutoCastKind(kind){if(!state||!autoCastKinds.includes(kind))return;state.autoCastKind=kind;state.autoCast=false;autoCastClock=0;renderCasting()}
function toggleAutoCast(){if(!state||state.done||state.setup)return;if(!state.autoCast&&state.paused)return;state.autoCast=!state.autoCast;autoCastClock=0;renderCasting()}
function autoCastTick(dt){if(!state||!state.autoCast||state.done||state.paused||state.setup||drag||choiceName||document.hidden||!autoCastKinds.includes(state.autoCastKind))return;const kind=state.autoCastKind;if(state.tickets<castCost(kind)){autoCastClock=0;return}autoCastClock+=dt;if(autoCastClock<.8)return;autoCastClock=0;cast(kind,undefined,true)}
function renderCasting(){const blocked=state.done||state.paused||state.setup;for(const kind of autoCastKinds){const cost=castCost(kind);$(kind).disabled=blocked||state.tickets<cost;$(kind).textContent='1회 · '+cost+'장';if(kind!=='gamble'){const b=$(kind+'5'),count=Math.min(5,Math.floor(state.tickets/cost));b.disabled=blocked||count<2;b.textContent=(count<2?'5회 · '+cost*5+'장':count+'회 · '+cost*count+'장')}}$('choose').disabled=blocked||state.dia<3;$('choose').textContent='멤버 선택 · 3개';$('gambleRate').textContent='성공률 '+Math.round((.2+.05*perk('lucky'))*100)+'%';$('castBalance').textContent=fmt(state.tickets)+'장';$('castDiamonds').textContent=fmt(state.dia)+'개';const kind=autoCastKinds.includes(state.autoCastKind)?state.autoCastKind:'group';$('autoCastKind').value=kind;$('autoCastKind').disabled=blocked;const btn=$('autoCastToggle');btn.disabled=state.done||state.setup||state.paused&&!state.autoCast;btn.textContent=state.autoCast?'자동 ON':'자동 OFF';btn.setAttribute('aria-pressed',String(!!state.autoCast));$('autoCastStatus').textContent=!state.autoCast?'수동 영입 중':blocked?'일시정지':state.tickets<castCost(kind)?'캐스팅권 대기':kind==='group'?focusGroup().name+' 자동 영입 중':kind==='normal'?'일반 자동 영입 중':'도박 자동 진행 중';$('trainTeam').disabled=blocked||!trainingCost()||state.gold<trainingCost();$('trainTeam').textContent=trainingCost()?'팀 훈련 +'+state.training+' · '+fmt(trainingCost())+' G':'팀 훈련 MAX';$('trainTeam').title='전체 유닛 공격력 ×'+teamBoost().toFixed(2)}
function renderFocus(){const g=focusGroup(),m=materials(g),n=m.filter(Boolean).length,root=$('focusProgress');$('castGroup').value=g.id;$('focusMini').textContent=n+' / '+g.members.length+'명';const sig=g.id+':'+m.map(u=>u?u.id:0).join(',')+':'+state.dia+':'+(state.gold>=combineCost(g)) +':'+state.done+':'+state.paused+':'+combineCost(g);if(root.dataset.signature===sig)return;root.dataset.signature=sig;root.innerHTML='<div class="focus-head"><strong>'+esc(g.name)+'</strong><b>'+n+'/'+g.members.length+'</b></div><div class="focus-bar"><i style="width:'+100*n/g.members.length+'%"></i></div><div class="focus-members">'+g.members.map((name,i)=>'<button class="focus-member '+(m[i]?'have':'')+'" onclick="openChoice(members['+members.indexOf(name)+'])" title="'+esc(name)+' · '+(m[i]?'보유':'선택 영입')+'">'+(activeCatalog.memberPhotos[name]?'<img src="'+esc(activeCatalog.memberPhotos[name])+'" alt="" onerror="this.remove()">':'')+'<span>'+esc(name)+'</span>'+(m[i]?' ✓':' +')+'</button>').join('')+'</div><button class="focus-combine" '+(n<g.members.length||state.gold<combineCost(g)||state.done||state.paused?'disabled':'')+' onclick="combine(\''+g.id+'\')">조합 · '+(combineCost(g))+' G</button>'}
let bannerSerial=0;
function battleBanner(text,kind){const el=$('battleEvent'),serial=++bannerSerial;el.textContent=text;el.className='battle-event '+kind;void el.offsetWidth;el.classList.add('show');setTimeout(()=>{if(serial===bannerSerial)el.classList.remove('show')},kind==='boss'?2000:950)}
